function read(node) {
 const raw = $(node).first().json;
 if (raw.status !== 'completed' || !/^gpt-6-luna(?:-\d{4}-\d{2}-\d{2})?$/.test(raw.model ?? '')) throw new Error('Resposta incompleta ou modelo fora do padrão gpt-6-luna: ' + node);
 return JSON.parse(raw.output.flatMap(entry => entry.content ?? []).filter(entry => entry.type === 'output_text').map(entry => typeof entry.text === 'string' ? entry.text : JSON.stringify(entry.text)).join(''));
}
if (!read('Confirmar acesso ao Luna').confirmado) throw new Error('Não foi possível confirmar gpt-6-luna.');
return $input.all().map(() => ({json:{confirmed:true}}));

const mission=$('Definir missão').first().json;
const sources = [{"url":"https://diario.dopovo.com.br/2026/11/09/psd-propoe-voto-distrital-misto-com-escolha-unica-na-urna","node":"Matéria de 9 de novembro","kind":"jornalistica"},{"url":"https://diario.dopovo.com.br/2026/11/03/motta-articula-votacao-do-voto-distrital-misto-ainda-em-2026/","node":"Matéria de 3 de novembro","kind":"jornalistica"},{"url":"https://www25.senado.leg.br/web/atividade/materias/-/materia/128554","node":"Ficha do Senado","kind":"institucional"},{"url":"https://www12.senado.leg.br/noticias/materias/2017/11/21/plenario-aprova-voto-distrital-misto-para-eleicoes-proporcionais","node":"Explicação do Senado","kind":"institucional"},{"url":"https://dadosabertos.camara.leg.br/api/v2/proposicoes?siglaTipo=PEC&ano=2026&keywords=Voto%20distrital%20misto&itens=30","node":"Busca de PECs na Câmara","kind":"institucional"}];
for (const source of sources) {
 const response = $(source.node).first().json;
 source.status = response.statusCode ?? null;
 const raw = response.statusCode === 200 ? String(response.body ?? response.data ?? '') : '';
 const article = raw.match(/<article\b[^>]*>([\s\S]*?)<\/article>/i)?.[1];
 source.text = (source.kind === 'jornalistica' ? article ?? raw : raw).replace(/<(script|style)\b[^>]*>[\s\S]*?<\/\1>/gi,' ').replace(/<[^>]+>/g,' ').replace(/&nbsp;/gi,' ').replace(/&quot;/gi,'"').replace(/&amp;/gi,'&').replace(/\s+/g,' ').trim().slice(0,24000);
}
if (!sources[0].text) throw new Error('Matéria original indisponível para o A/B.');
return [{json:{mission,sources}}];

