 return JSON.parse(raw.output.flatMap(entry => entry.content ?? []).filter(entry => entry.type === 'output_text').map(entry => typeof entry.text === 'string' ? entry.text : JSON.stringify(entry.text)).join(''));
}
const {mission,sources}=$('Preparar apuração').first().json;
const output=read('Apurar documentos');
const normalize=value=>value.normalize('NFC').replace(/\s+/g,' ').trim();
const findings=[];
const open_questions=[...output.open_questions];
for(const finding of output.findings){
 const source=sources.find(item=>item.url===finding.url);
 const quote=normalize(finding.quote);
 if(source?.kind==='institucional' && quote.length>=12 && normalize(source.text).includes(quote)){
  findings.push({...finding,source_title:source.node,consulted_at:new Date().toISOString()});
 }else{
  open_questions.push('Sem evidência documental validada: '+finding.claim);
 }
}
return [{json:{mission,findings,open_questions,source_results:sources.map(({url,kind,status})=>({url,kind,status})),original:sources[0].text}}];

